sourcesContent:
import React,{useState}from'react';
import Header from'../components/Header';
import Footer from'../components/Footer';

const style=`
*{box-sizing:border-box}
.contact-page{width:100%;font-family:Inter,Arial,sans-serif;color:#183d44;background:#fff;overflow:hidden}
.contact-page button,.contact-page input,.contact-page select,.contact-page textarea{font-family:inherit}
.contact-hero{position:relative;min-height:430px;background:linear-gradient(90deg,#eff9f7 0%,#edf8f6 37%,rgba(230,246,243,.35) 58%,rgba(3,72,73,.2) 100%),url("https://images.unsplash.com/photo-1551836022-d5d88e9218df?auto=format&fit=crop&w=1800&q=90") center/cover no-repeat}
.contact-hero:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(239,249,247,.98) 0%,rgba(239,249,247,.94) 36%,rgba(239,249,247,.35) 62%,rgba(0,50,52,.15) 100%)}
.hero-container{position:relative;z-index:2;width:min(1180px,calc(100% - 48px));min-height:430px;margin:auto;display:flex;align-items:center}
.hero-content{width:51%;padding:42px 0}
.hero-label{font-size:12px;letter-spacing:3px;font-weight:800;color:#075b5d;margin-bottom:12px}
.hero-title{font-family:Georgia,"Times New Roman",serif;font-size:55px;line-height:.98;letter-spacing:-1.4px;color:#103b42;margin:0}
.hero-title span{color:#bd8c27}
.hero-description{max-width:510px;color:#455c62;font-size:15px;line-height:1.48;margin:17px 0 23px}
.hero-features{display:grid;grid-template-columns:repeat(3,1fr);max-width:475px}
.hero-feature{display:flex;align-items:center;gap:10px;border-right:1px solid #cbdedb;padding:5px 17px 5px 0;margin-right:17px}
.hero-feature:last-child{border:0}
.hero-feature-icon{font-size:27px;color:#075f60}
.hero-feature-text{font-size:12px;line-height:1.35;color:#29474d}
.hero-question{position:absolute;z-index:3;left:39%;top:65px;color:#153f45;font-family:"Comic Sans MS",cursive;font-size:22px;line-height:1.05;font-style:italic;transform:rotate(-7deg);text-align:center}
.hero-question:after{content:"";display:block;width:75px;height:3px;background:#c99a2d;margin:8px auto;transform:rotate(-8deg)}
.hero-smile{color:#d9a83b;font-size:27px}
.hero-contact-list{position:absolute;z-index:3;right:15px;top:18px;width:175px}
.hero-contact-item{height:45px;margin-bottom:5px;border-radius:9px;background:rgba(247,252,251,.9);display:flex;align-items:center;gap:11px;padding:0 12px;color:#29464c;font-size:11px;box-shadow:0 3px 9px rgba(0,0,0,.07)}
.hero-contact-icon{width:28px;height:28px;border-radius:7px;display:flex;align-items:center;justify-content:center;background:#075e60;color:#fff;font-size:16px;flex-shrink:0}
.hero-note{position:absolute;z-index:4;right:0;bottom:17px;color:#17484d;font-family:"Comic Sans MS",cursive;font-size:19px;line-height:1.05;text-align:center;font-style:italic;transform:rotate(-5deg)}
.hero-note span{color:#e7b94c;font-size:27px}
.contact-main{padding:18px 0 0}
.container{width:min(1180px,calc(100% - 48px));margin:auto}
.contact-grid{display:grid;grid-template-columns:1.15fr 1fr;gap:17px}
.contact-card{border:1px solid #e0eae9;border-radius:12px;background:#fff;padding:15px 19px;box-shadow:0 3px 13px rgba(9,65,68,.025)}
.card-heading{display:flex;align-items:center;gap:13px;margin-bottom:4px}
.card-heading-icon{width:51px;height:51px;border-radius:50%;background:#075f60;color:#fff;display:flex;align-items:center;justify-content:center;font-size:25px;flex-shrink:0}
.card-title{font-family:Georgia,"Times New Roman",serif;font-size:22px;color:#143e45;margin:0}
.card-subtitle{color:#627177;font-size:12px;margin:2px 0 15px}
.form-group{margin-bottom:8px;position:relative}
.input-icon{position:absolute;left:13px;top:50%;transform:translateY(-50%);font-size:15px;color:#075e60;z-index:1}
.contact-input,.contact-select,.contact-textarea{width:100%;border:1px solid #d4dfe1;border-radius:9px;background:#fff;color:#304950;font-size:12px;outline:none;transition:.2s}
.contact-input,.contact-select{height:43px;padding:0 14px 0 40px}
.contact-textarea{height:125px;padding:12px 14px 12px 40px;resize:none}
.contact-input:focus,.contact-select:focus,.contact-textarea:focus{border-color:#08706d;box-shadow:0 0 0 3px rgba(8,112,109,.08)}
.phone-row{display:grid;grid-template-columns:132px 1fr;gap:0}
.phone-code{border:1px solid #d4dfe1;border-radius:9px 0 0 9px;height:43px;display:flex;align-items:center;padding:0 11px;gap:7px;font-size:12px;background:#fff}
.phone-number{border-radius:0 9px 9px 0!important;padding-left:14px}
.send-button{width:100%;height:46px;border:0;border-radius:24px;background:#075f60;color:#fff;font-size:13px;font-weight:800;cursor:pointer;margin-top:11px;transition:.25s}
.send-button:hover{background:#034c4e;transform:translateY(-1px)}
.success-message{margin-top:9px;padding:9px;border-radius:7px;background:#eaf8f4;color:#08706d;font-size:11px;text-align:center}
.right-column{display:flex;flex-direction:column;gap:10px}
.info-card{background:linear-gradient(135deg,#f1faf8,#e9f6f4);border-radius:12px;padding:13px 17px;min-height:323px}
.info-row{display:flex;align-items:center;gap:12px;margin:12px 0}
.info-icon{width:43px;height:43px;border-radius:50%;background:#edc65f;color:#174348;display:flex;align-items:center;justify-content:center;font-size:21px;flex-shrink:0}
.info-main{color:#143f46;font-size:13px;font-weight:800}
.info-detail{color:#65747a;font-size:11px;line-height:1.35;margin-top:2px}
.info-heading{display:flex;align-items:center;gap:11px;margin-bottom:2px}
.info-heading-icon{width:48px;height:48px;border-radius:50%;background:#075f60;color:#fff;display:flex;align-items:center;justify-content:center;font-size:23px}
.quick-card{border:1px solid #e0eae9;border-radius:12px;padding:13px 17px;background:#fff}
.quick-heading{display:flex;align-items:center;gap:11px;margin-bottom:10px}
.quick-icon{width:48px;height:48px;border-radius:50%;background:#075f60;color:#fff;display:flex;align-items:center;justify-content:center;font-size:23px}
.quick-title{font-family:Georgia,"Times New Roman",serif;color:#143e45;font-size:20px;margin:0}
.quick-subtitle{font-size:11px;color:#68767b;margin-top:2px}
.quick-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.quick-item{border:1px solid #dbe5e4;border-radius:8px;padding:10px;display:flex;gap:9px;align-items:center}
.quick-item-icon{font-size:21px;color:#075e60}
.quick-item-title{font-size:11px;font-weight:800;color:#183e44}
.quick-item-text{font-size:9px;color:#6a777c;margin-top:2px}
.support-banner{position:relative;min-height:138px;border-radius:11px;overflow:hidden;margin-top:17px;background:#075d5e url("https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&fit=crop&w=1400&q=85") center/cover no-repeat}
.support-banner:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(0,79,80,.94),rgba(0,79,80,.78),rgba(0,79,80,.45))}
.support-content{position:relative;z-index:2;display:flex;align-items:center;height:138px;padding:20px 27px;color:#fff}
.support-icon{width:58px;height:58px;border-radius:50%;background:#fff;color:#075e60;display:flex;align-items:center;justify-content:center;font-size:29px;margin-right:16px;flex-shrink:0}
.support-title{font-family:Georgia,"Times New Roman",serif;font-size:23px;line-height:1;margin:0}
.support-text{font-size:11px;margin-top:7px;max-width:390px;line-height:1.4;color:#e6f4f3}
.support-stats{margin-left:auto;display:grid;grid-template-columns:repeat(3,1fr);background:rgba(3,67,68,.78);border-radius:9px;min-width:390px}
.support-stat{text-align:center;padding:13px 16px;border-right:1px solid rgba(255,255,255,.22)}
.support-stat:last-child{border:0}
.support-stat-icon{font-size:22px;color:#f1c75c}
.support-stat-number{font-size:17px;font-weight:800;margin-top:2px}
.support-stat-text{font-size:9px;color:#e3efee;margin-top:2px}
.support-note{position:absolute;z-index:3;right:17px;top:18px;color:#fff;font-family:"Comic Sans MS",cursive;font-size:17px;line-height:1.02;font-style:italic;transform:rotate(-5deg)}
.support-note span{color:#f0c355;font-size:23px}
.faq-section{padding:22px 0 28px}
.faq-header{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:13px}
.faq-label{font-size:11px;font-weight:800;letter-spacing:2.5px;color:#075d60}
.faq-title{font-family:Georgia,"Times New Roman",serif;font-size:27px;color:#143e45;margin:3px 0 0}
.faq-title:after{content:"";display:inline-block;width:47px;height:2px;background:#c7962d;margin:0 0 6px 12px}
.faq-right{font-size:11px;color:#53666b}
.faq-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px 17px}
.faq-item{border:1px solid #dce6e5;border-radius:8px;background:#fff;overflow:hidden}
.faq-question{width:100%;min-height:39px;border:0;background:#fff;display:flex;justify-content:space-between;align-items:center;text-align:left;padding:0 13px;color:#314c52;font-size:11px;cursor:pointer}
.faq-plus{font-size:19px;color:#173e44}
.faq-answer{padding:0 13px 11px;color:#68777b;font-size:10px;line-height:1.45}
@media(max-width:1000px){.hero-content{width:62%}.hero-question{left:48%}.hero-contact-list{right:0}.contact-grid{grid-template-columns:1fr}.support-stats{min-width:350px}.support-note{display:none}}
@media(max-width:700px){.contact-hero{min-height:620px}.hero-container{width:calc(100% - 30px);min-height:620px;align-items:flex-start}.hero-content{width:100%;padding-top:42px}.hero-title{font-size:43px}.hero-description{font-size:14px}.hero-question,.hero-contact-list,.hero-note{display:none}.hero-features{max-width:100%;grid-template-columns:repeat(3,1fr)}.hero-feature{padding-right:8px;margin-right:8px}.container{width:calc(100% - 30px)}.contact-grid{gap:12px}.contact-card{padding:14px}.phone-row{grid-template-columns:120px 1fr}.support-banner{min-height:280px}.support-content{height:280px;display:block;padding:20px}.support-icon{margin-bottom:9px}.support-stats{min-width:0;width:100%;margin:18px 0 0}.support-note{display:none}.faq-header{display:block}.faq-right{margin-top:8px}.faq-grid{grid-template-columns:1fr}}
@media(max-width:430px){.hero-title{font-size:38px}.hero-features{grid-template-columns:1fr}.hero-feature{border-right:0;border-bottom:1px solid #cbdedb;padding:7px 0;margin:0}.hero-feature:last-child{border-bottom:0}.phone-row{grid-template-columns:105px 1fr}.phone-code{font-size:10px;padding:0 7px}.quick-grid{grid-template-columns:1fr}.support-stats{grid-template-columns:1fr}.support-stat{border-right:0;border-bottom:1px solid rgba(255,255,255,.2)}}
`;

const faqs=[
['How do I join the online classes?','Choose your course, complete the enrolment process, and our team will share your class schedule and joining details.'],
['Are the classes live or recorded?','Our courses include live interactive classes along with learning resources and recordings where applicable.'],
['Will I get a certificate after the course?','Yes. Students who successfully complete the required course work can receive a course completion certificate.'],
['Do you provide placement support?','Yes. We provide placement guidance, interview preparation, resume support and career assistance.'],
['What if I miss a live class?','You can contact the support team for the available recording or alternate learning arrangement.'],
['How can I make the payment?','Our team will provide the available payment options and instructions during enrolment.']
];

const Contact=()=>{
const[form,setForm]=useState({name:'',email:'',phone:'',query:'',message:''});
const[submitted,setSubmitted]=useState(false);
const[openFaq,setOpenFaq]=useState(null);
const handleChange=e=>setForm({...form,[e.target.name]:e.target.value});
const handleSubmit=e=>{e.preventDefault();setSubmitted(true);setTimeout(()=>setSubmitted(false),5000)};
return(
<>
<style>{style}</style>
<Header/>
<main className="contact-page">
<section className="contact-hero">
<div className="hero-container">
<div className="hero-content">
<div className="hero-label">CONTACT US</div>
<h1 className="hero-title">We’re Here<br/>to <span>Help You!</span></h1>
<p className="hero-description">Have questions about our online courses, batches, payments, or certifications? Our team is ready to assist you. Get in touch and take the next step towards your brighter future with Vighnavi Academy.</p>
<div className="hero-features">
<div className="hero-feature"><div className="hero-feature-icon">♧</div><div className="hero-feature-text">Quick<br/>Response</div></div>
<div className="hero-feature"><div className="hero-feature-icon">♟</div><div className="hero-feature-text">Friendly<br/>Support</div></div>
<div className="hero-feature"><div className="hero-feature-icon">◷</div><div className="hero-feature-text">Guidance<br/>at Every Step</div></div>
</div>
</div>
<div className="hero-question">Your<br/>Questions<br/>Our Priority<div className="hero-smile">☺</div></div>
<div className="hero-contact-list">
{[['🎓','Course Guidance'],['▣','Batch Details'],['◆','Fee & Offers'],['⚙','Technical Support'],['▤','Certifications'],['●','General Queries']].map((x,i)=><div className="hero-contact-item" key={i}><div className="hero-contact-icon">{x[0]}</div>{x[1]}</div>)}
</div>
<div className="hero-note">We’re<br/>Just a Message<br/>Away! <span>♡</span></div>
</div>
</section>

<section className="contact-main">
<div className="container contact-grid">
<div className="contact-card">
<div className="card-heading"><div className="card-heading-icon">✉</div><div><h2 className="card-title">Send Us a Message</h2><p className="card-subtitle">Fill in the form below and our team will get back to you shortly.</p></div></div>
<form onSubmit={handleSubmit}>
<div className="form-group"><span className="input-icon">♟</span><input className="contact-input" name="name" value={form.name} onChange={handleChange} placeholder="Full Name *" required/></div>
<div className="form-group"><span className="input-icon">✉</span><input className="contact-input" type="email" name="email" value={form.email} onChange={handleChange} placeholder="Email Address *" required/></div>
<div className="form-group phone-row"><div className="phone-code"><span>☎</span><span>🇮🇳</span><b>+91</b><span>⌄</span></div><input className="contact-input phone-number" name="phone" value={form.phone} onChange={handleChange} placeholder="Phone Number *" required/></div>
<div className="form-group"><span className="input-icon">▤</span><select className="contact-select" name="query" value={form.query} onChange={handleChange} required><option value="">Select Query Type *</option><option>Course Information</option><option>Batch Schedule</option><option>Fees & Payment</option><option>Certification</option><option>Technical Support</option><option>General Query</option></select></div>
<div className="form-group"><span className="input-icon" style={{top:'22px'}}>▰</span><textarea className="contact-textarea" name="message" value={form.message} onChange={handleChange} placeholder="Your Message *" required/></div>
<button className="send-button" type="submit">Send Message&nbsp;&nbsp; →</button>
{submitted&&<div className="success-message">✓ Thank you! Your message has been submitted successfully. Our team will contact you shortly.</div>}
</form>
</div>

<div className="right-column">
<div className="info-card">
<div className="info-heading"><div className="info-heading-icon">⌖</div><div><h2 className="card-title">Get in Touch</h2><p className="card-subtitle">Reach out to us through any of the following channels.</p></div></div>
<div className="info-row"><div className="info-icon">☎</div><div><div className="info-main">+91 98765 43210</div><div className="info-detail">Mon - Sat, 9:00 AM - 7:00 PM<br/>(Online Support Only)</div></div></div>
<div className="info-row"><div className="info-icon">✉</div><div><div className="info-main">support@vighnaviacademy.com</div><div className="info-detail">We reply within 24 hours</div></div></div>
<div className="info-row"><div className="info-icon">●</div><div><div className="info-main">Online Classes Only</div><div className="info-detail">We provide live interactive online training<br/>— learn from anywhere, anytime!</div></div></div>

</div>

<div className="quick-card">
<div className="quick-heading"><div className="quick-icon">💡</div><div><h2 className="quick-title">Quick Help Topics</h2><div className="quick-subtitle">Find quick answers or reach the right team faster.</div></div></div>
<div className="quick-grid">
{[['📖','Course Information','Know about our courses'],['▣','Batch Schedule','Upcoming batches'],['◆','Fees & Payment','Fee details & offers'],['▤','Certifications','Get certified']].map((x,i)=><div className="quick-item" key={i}><div className="quick-item-icon">{x[0]}</div><div><div className="quick-item-title">{x[1]}</div><div className="quick-item-text">{x[2]}</div></div></div>)}
</div>
</div>
</div>
</div>

<div className="container">
<div className="support-banner">
<div className="support-content">
<div className="support-icon">♧</div>
<div><h2 className="support-title">Live Support for<br/>Your Learning Journey</h2><p className="support-text">Our support team is always ready to help you with course selection, technical issues, or any other queries.</p></div>
<div className="support-stats">
<div className="support-stat"><div className="support-stat-icon">♟</div><div className="support-stat-number">100%</div><div className="support-stat-text">Student Support</div></div>
<div className="support-stat"><div className="support-stat-icon">◷</div><div className="support-stat-number">Quick</div><div className="support-stat-text">Response</div></div>
<div className="support-stat"><div className="support-stat-icon">♥</div><div className="support-stat-number">Dedicated</div><div className="support-stat-text">Guidance</div></div>
</div>
<div className="support-note">Same<br/>Learning<br/>Different<br/>Success Stories<br/><span>♡</span></div>
</div>
</div>
</div>
</section>

<section className="faq-section">
<div className="container">
<div className="faq-header">
<div><div className="faq-label">FAQ</div><h2 className="faq-title">Common Questions</h2></div>
<div className="faq-right">Still have a question? Send us a message!&nbsp;&nbsp; →</div>
</div>
<div className="faq-grid">
{faqs.map((faq,i)=><div className="faq-item" key={i}><button className="faq-question" onClick={()=>setOpenFaq(openFaq===i?null:i)}><span>{faq[0]}</span><span className="faq-plus">{openFaq===i?'−':'+'}</span></button>{openFaq===i&&<div className="faq-answer">{faq[1]}</div>}</div>)}
</div>
</div>
</section>
</main>
<Footer/>
</>
)};
export default Contact;
